#!/usr/bin/env node
import { existsSync, mkdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs'
import { dirname, join, resolve } from 'node:path'
import { inflateSync } from 'node:zlib'
const root = process.cwd()
const payload = JSON.parse(inflateSync(Buffer.from('', 'base64')).toString('utf8'))
const stamp = new Date().toISOString().replace(/[:.]/g, '-')
const backupRoot = join(root, `backup-before-v0200-${stamp}`)
if (!existsSync(join(root, 'package.json')) || !existsSync(join(root, 'src', 'App.tsx'))) throw new Error('Installer musí byť spustený v koreňovom priečinku aplikácie vedľa package.json.')
function backup(relativePath) { const target=join(root,relativePath); if(!existsSync(target))return; const destination=join(backupRoot,relativePath); mkdirSync(dirname(destination),{recursive:true}); writeFileSync(destination,readFileSync(target)); }
for (const [relativePath, encodedFile] of Object.entries(payload)) { backup(relativePath); const target=join(root,relativePath); mkdirSync(dirname(target),{recursive:true}); writeFileSync(target,Buffer.from(encodedFile,'base64')); console.log(`OK  ${relativePath}`); }
for (const path of ['node_modules/.vite','dist','tsconfig.app.tsbuildinfo','tsconfig.node.tsbuildinfo']) { const target=resolve(root,path); if(existsSync(target))rmSync(target,{recursive:true,force:true}); }
function text(path) { return readFileSync(join(root,path),'utf8') }
function requireCheck(condition,message) { if(!condition)throw new Error(`VERIFY FAILED: ${message}`) }
const pkg=JSON.parse(text('package.json'))
requireCheck(pkg.version==='0.20.0','package.json nemá verziu 0.20.0')
requireCheck(text('src/lib/storage.ts').includes("CURRENT_VERSION = '0.20.0'"),'storage verzia nie je 0.20.0')
requireCheck(text('src/views/Raci.tsx').includes('RACI Intelligence'),'RACI 3.2 nemá Intelligence kartu')
requireCheck(text('src/views/OitPortal.tsx').includes('RACI Intelligence'),'RACI OIT nemá Intelligence kartu')
requireCheck(text('src/views/RaciIntelligence.tsx').includes('What-if simulácia'),'chýba what-if simulácia')
requireCheck(text('src/views/RaciIntelligence.tsx').includes('Bus factor'),'chýba bus-factor pohľad')
requireCheck(text('src/lib/raciIntelligence.ts').includes('buildRaciIntelligence'),'chýba Intelligence analytický engine')
requireCheck(text('src/lib/raciIntelligence.ts').includes('simulateAbsence'),'chýba simulácia neprítomnosti')
console.log(`\nZáloha pôvodných súborov: ${backupRoot}`)
console.log('VERIFIED: release 0.20.0 - RACI Intelligence je nainštalované.')
console.log('Pokračuj príkazom: npm run build')
